CREATE OR REPLACE FUNCTION public.fn_get_child_attendance_by_date(p_tenant_id uuid, p_branch_id uuid, p_date date)  RETURNS TABLE(id uuid, tenant_id uuid, branch_id uuid, classroom_id uuid, child_id uuid, attendance_date date, status character varying, arrival_time time without time zone, departure_time time without time zone, notes text, recorded_by_user_id uuid, pickup_person_name character varying, pickup_person_relationship character varying, pickup_verification_method character varying, pickup_notes text, authorized_pickup_id uuid, departure_verified_by_user_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT ca.id, ca.tenant_id, ca.branch_id, ca.classroom_id, ca.child_id, ca.attendance_date, ca.status,            ca.arrival_time, ca.departure_time, ca.notes, ca.recorded_by_user_id, ca.pickup_person_name,            ca.pickup_person_relationship, ca.pickup_verification_method, ca.pickup_notes,            ca.authorized_pickup_id, ca.departure_verified_by_user_id, ca.created_at, ca.updated_at     FROM child_attendance ca     WHERE ca.tenant_id = p_tenant_id AND ca.branch_id = p_branch_id AND ca.attendance_date = p_date; END; $function$ ;
